INSERT OR IGNORE INTO products (id,category_id,name,slug,description,price,stock,image,is_featured,created_at,short_description,long_description,leather_type,hardware,lining,dimensions,weight,made_in,warranty,care,is_bestseller,is_active) VALUES (9,1,'𝗧𝗵𝗲 "𝗛𝘂𝘀𝘁𝗹𝗲 & 𝗛𝗲𝗿𝗶𝘁𝗮𝗴𝗲 Check In Luggage','𝗧𝗵𝗲-"𝗛𝘂𝘀𝘁𝗹𝗲-&-𝗛𝗲𝗿𝗶𝘁𝗮𝗴𝗲"-full-grain-leather-check-in-luggage,-handcrafted-','Full-grain leather. Hand-burnished finish. Built to travel a lifetime.
Handcrafted in full-grain leather with precision hardware — luggage built like an heirloom, not an accessory.
Where heritage leathercraft meets modern travel — every Sovereign Trolley is hand-finished for a lifetime of journeys.',65000.0,20,'Screenshot_2026-08-17_004101.png',0,'2026-08-17 06:43:58','A travel companion cut from full-grain leather and finished by hand — built for those who arrive as intentionally as they leave.','The "𝗛𝘂𝘀𝘁𝗹𝗲 & 𝗛𝗲𝗿𝗶𝘁𝗮𝗴𝗲" Trolley is where heritage leathercraft meets modern travel. Every panel is cut from genuine full-grain hide, hand-burnished and finished to develop a deeper, richer patina with every journey. Structured yet lightweight, it carries the same standard of craftsmanship trusted by heritage leather houses — because we''ve made for them too. This isn''t mass-produced luggage; it''s a piece built to travel with you for decades.               



Hardware & Build:

Genuine Indian YKK zippers for a lifetime of smooth, silent operation
360° rotating precision wheels for effortless maneuverability
Reinforced corner guards and stitched leather piping for structural durability
Telescopic aluminium trolley handle, tested for repeated extension
Brass-toned hardware, tarnish-resistant finish

Compartments:

Spacious main compartment with compression straps to secure contents
Dedicated front zip pocket for documents, chargers, and essentials
Soft interior lining to protect garments and valuables

Care Instructions:

Wipe with a soft, dry cloth after each use
Condition with leather balm every 3–4 months to preserve suppleness
Avoid prolonged direct sunlight and moisture exposure
Store upright in breathable fabric when not in use

Available Sizes: 20"· 22" · 24" · 28"

All sizes are in Inches : Height Calculated from wheels to top handle.

Every piece can be custom made to order — choice of leather, lining, and hardware finish.

📩 Connect with us on WhatsApp or Instagram to begin your bespoke order.','Full Grain Buffalo ','YKK ','Premium Twill (cotton twill)','20 inches','2.5 kgs','India','Lifetime Leather Warranty ','',1,1);
